using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class VariableRoadWidth {
static Vector3[] road;static float[] lengths;static float[] turns;static Terrain terrain;
// Returns signed distance, distance along route and local curvature.
static Vector3 Nearest(Vector3 p){float best=float.MaxValue,sd=0,s=0,bend=0;for(int i=1;i<road.Length;i++){var a=new Vector2(road[i-1].x,road[i-1].z);var d=new Vector2(road[i].x,road[i].z)-a;var q=new Vector2(p.x,p.z)-a;float t=Mathf.Clamp01(Vector2.Dot(q,d)/d.sqrMagnitude);var off=q-d*t;float ds=off.sqrMagnitude;if(ds<best){best=ds;sd=Mathf.Sqrt(ds)*Mathf.Sign(d.x*off.y-d.y*off.x);s=Mathf.Lerp(lengths[i-1],lengths[i],t);bend=Mathf.Lerp(turns[i-1],turns[i],t);}}return new Vector3(sd,s,bend);}
static float Width(float s,float bend)=>Mathf.Clamp(3.4f+.7f*Mathf.Sin(s/38)+.48f*Mathf.Sin(s/17+.8f)+.6f*bend+.9f*Mathf.Exp(-Mathf.Pow((s-125)/16,2))+.8f*Mathf.Exp(-Mathf.Pow((s-315)/18,2)),2.6f,5f);
static float Offset(float s)=>.4f*Mathf.Sin(s/24);
static bool Developed(Vector3 p)=>new Vector2(p.x,p.z-14).magnitude<38||new Vector2(p.x-25,p.z-39).magnitude<16||new Vector2(p.x-8,p.z-175).magnitude<35||(p.x>-105&&p.x<-31&&p.z>52&&p.z<128);
public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var root=GameObject.Find("New_Map").transform;var land=root.Find("05_Landscape");if(land.Find("Variable road edge grass"))throw new Exception("Already authored");terrain=root.GetComponentInChildren<Terrain>();var td=terrain.terrainData;Directory.CreateDirectory("output/NewMap/VariableRoad");AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(td),"Assets/NewMap/Terrain/Before variable road width.asset");road=File.ReadAllLines("output/NewMap/Revision2/road-centerline.csv").Skip(1).Select(l=>{var s=l.Split(',');return new Vector3(float.Parse(s[0],System.Globalization.CultureInfo.InvariantCulture),float.Parse(s[1],System.Globalization.CultureInfo.InvariantCulture),float.Parse(s[2],System.Globalization.CultureInfo.InvariantCulture));}).ToArray();lengths=new float[road.Length];turns=new float[road.Length];for(int i=1;i<road.Length;i++)lengths[i]=lengths[i-1]+Vector3.Distance(road[i],road[i-1]);for(int i=2;i<road.Length-2;i++)turns[i]=Mathf.Clamp01(Vector3.Angle(road[i]-road[i-2],road[i+2]-road[i])/20);
int n=td.alphamapWidth;var alpha=td.GetAlphamaps(0,0,n,n);float minWidth=99,maxWidth=0;
for(int z=0;z<n;z++)for(int x=0;x<n;x++){var p=new Vector3(terrain.transform.position.x+x/(float)(n-1)*td.size.x,0,terrain.transform.position.z+z/(float)(n-1)*td.size.z);var near=Nearest(p);if(Mathf.Abs(near.x)>10)continue;float w=Width(near.y,near.z),edgeNoise=(Mathf.PerlinNoise(p.x*.16f+80,p.z*.16f+30)-.5f)*.6f;float d=Mathf.Abs(near.x-Offset(near.y))+edgeNoise;float track=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(w,w+1.5f,d));float noise=Mathf.PerlinNoise(p.x*.19f+300,p.z*.19f+500);
float yard=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(25,35,new Vector2(p.x,p.z-14).magnitude+(noise-.5f)*3));float station=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(9,15,new Vector2(p.x-25,p.z-39).magnitude));float village=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(20,32,new Vector2(p.x-8,p.z-175).magnitude));float dirt=Mathf.Max(track,Mathf.Max(yard,Mathf.Max(station,village)));
float dx=(p.x+67)/33,dz=(p.z-90)/35,a=Mathf.Atan2(dz,dx);float shape=Mathf.Sqrt(dx*dx+dz*dz)/(1+.055f*Mathf.Sin(a*3+.8f)+.035f*Mathf.Sin(a*5));float field=.85f*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.87f,1.05f,shape)));float meadow=(1-dirt)*(1-field),variation=Mathf.PerlinNoise(p.x*.06f+100,p.z*.06f+500);
alpha[z,x,0]=meadow*(.55f+.3f*variation);alpha[z,x,4]=meadow*(.45f-.3f*variation);alpha[z,x,3]=(1-dirt)*field;alpha[z,x,1]=dirt*.3f;alpha[z,x,2]=dirt*.08f;alpha[z,x,5]=dirt*.02f;alpha[z,x,6]=dirt*.6f;
if(!Developed(p)&&Mathf.Abs(near.x)<1){minWidth=Mathf.Min(minWidth,w*2);maxWidth=Mathf.Max(maxWidth,w*2);}}
td.SetAlphamaps(0,0,alpha);
var group=new GameObject("Variable road edge grass").transform;group.SetParent(land,false);var source=AssetDatabase.LoadAssetAtPath<GameObject>(AssetDatabase.GUIDToAssetPath(AssetDatabase.FindAssets("TFP_Grass_Patch_03A t:Prefab").First()));var rng=new System.Random(342);int count=0;
for(int i=4;i<road.Length-4;i++)foreach(int side in new[]{-1,1}){if(rng.NextDouble()>.78)continue;var tangent=road[i+1]-road[i-1];tangent.y=0;tangent.Normalize();float w=Width(lengths[i],turns[i]);float offset=Offset(lengths[i])+side*(w+1.3f+(float)rng.NextDouble()*.65f);if(Mathf.Abs(offset)>6.45f)continue;var p=road[i]+new Vector3(-tangent.z,0,tangent.x)*offset;if(Developed(p))continue;p.y=terrain.SampleHeight(p)+terrain.transform.position.y-.025f;var g=(GameObject)PrefabUtility.InstantiatePrefab(source,group);g.transform.position=p;g.transform.rotation=Quaternion.Euler(0,(float)rng.NextDouble()*360,0);g.transform.localScale=Vector3.one*(.75f+(float)rng.NextDouble()*.45f);count++;}
int shifted=0;foreach(Transform t in root.Find("09_Original_Road_Details/Rocky road shoulders")){var near=Nearest(t.position);float target=Width(near.y,near.z)+1.8f;if(Mathf.Abs(near.x-Offset(near.y))<target){int i=Array.FindIndex(lengths,s=>s>=near.y);i=Mathf.Clamp(i,1,road.Length-1);var d=(road[i]-road[i-1]).normalized;var p=t.position+new Vector3(-d.z,0,d.x)*Mathf.Sign(near.x)*(target-Mathf.Abs(near.x-Offset(near.y)));p.y=terrain.SampleHeight(p)+terrain.transform.position.y-.045f;t.position=p;shifted++;}}
EditorUtility.SetDirty(td);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());string report="Variable clear dirt core width approximately "+minWidth.ToString("F1")+" to "+maxWidth.ToString("F1")+"m, plus soft 1.5m shoulders each side; asymmetric edges, broad bend/passing-area flares, "+count+" new verge grass patches and "+shifted+" shoulder rocks moved outward. Heightmap and existing road bumps unchanged.";File.WriteAllText("output/NewMap/VariableRoad/summary.txt",report);return report;}
}
